CREATE TABLE "c_Customer" ("id" BIGINT NOT NULL, "a_Party_name" TEXT NOT NULL, "a_Customer_customer_no" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Employee" ("id" BIGINT NOT NULL, "a_Party_name" TEXT NOT NULL, "a_Employee_employee_no" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_InventoryItem" ("id" BIGINT NOT NULL, "a_InventoryItem_quantity" BIGINT NOT NULL, "r_ProductInventory_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_ProductInventory_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_ProductInventory_source_id" IS NOT NULL));
CREATE TABLE "c_Invoice" ("id" BIGINT NOT NULL, "a_Invoice_invoice_no" TEXT NOT NULL, "a_Invoice_amount" NUMERIC NOT NULL, "r_SalesOrderInvoices_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_SalesOrderInvoices_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_SalesOrderInvoices_source_id" IS NOT NULL));
CREATE TABLE "c_Party" ("id" BIGINT NOT NULL, "a_Party_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Payment" ("id" BIGINT NOT NULL, "a_Payment_amount" NUMERIC NOT NULL, "a_Payment_paid_at" TIMESTAMP NOT NULL, "r_InvoicePayments_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_InvoicePayments_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_InvoicePayments_source_id" IS NOT NULL));
CREATE TABLE "c_Product" ("id" BIGINT NOT NULL, "a_Product_sku" TEXT NOT NULL, "a_Product_cost" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_PurchaseOrder" ("id" BIGINT NOT NULL, "a_PurchaseOrder_po_no" TEXT NOT NULL, "a_PurchaseOrder_total" NUMERIC NOT NULL, "r_VendorPurchaseOrders_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_VendorPurchaseOrders_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_VendorPurchaseOrders_source_id" IS NOT NULL));
CREATE TABLE "c_SalesOrder" ("id" BIGINT NOT NULL, "a_SalesOrder_so_no" TEXT NOT NULL, "a_SalesOrder_total" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Shipment" ("id" BIGINT NOT NULL, "a_Shipment_tracking_no" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Vendor" ("id" BIGINT NOT NULL, "a_Party_name" TEXT NOT NULL, "a_Vendor_vendor_no" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Warehouse" ("id" BIGINT NOT NULL, "a_Warehouse_code" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_CustomerSalesOrders" ("r_CustomerSalesOrders_source_id" BIGINT NOT NULL, "r_CustomerSalesOrders_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_CustomerSalesOrders_source_id", "r_CustomerSalesOrders_target_id"), UNIQUE ("r_CustomerSalesOrders_target_id"));
CREATE TABLE "l_PurchaseOrderProducts" ("r_PurchaseOrderProducts_source_id" BIGINT NOT NULL, "r_PurchaseOrderProducts_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PurchaseOrderProducts_source_id", "r_PurchaseOrderProducts_target_id"));
CREATE TABLE "l_SalesOrderProducts" ("r_SalesOrderProducts_source_id" BIGINT NOT NULL, "r_SalesOrderProducts_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_SalesOrderProducts_source_id", "r_SalesOrderProducts_target_id"));
CREATE TABLE "l_SalesOrderShipments" ("r_SalesOrderShipments_source_id" BIGINT NOT NULL, "r_SalesOrderShipments_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_SalesOrderShipments_source_id", "r_SalesOrderShipments_target_id"), UNIQUE ("r_SalesOrderShipments_target_id"));
CREATE TABLE "l_WarehouseInventory" ("r_WarehouseInventory_source_id" BIGINT NOT NULL, "r_WarehouseInventory_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_WarehouseInventory_source_id", "r_WarehouseInventory_target_id"), UNIQUE ("r_WarehouseInventory_target_id"));
ALTER TABLE "c_InventoryItem" ADD CONSTRAINT "fk_c_InventoryItem_0" FOREIGN KEY ("r_ProductInventory_source_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
